/* CPU state, dispatch into the recompiled code, failure reporting and I/O ports. */
#include <stdio.h>
#include <stdlib.h>

#include "wc_rt.h"

uint8_t R[0x400];
uint8_t M[MEM_SIZE + 16];
uint64_t wc_icount;
int wc_trace;
int64_t wc_reloc;
uint32_t wc_watch, wc_last_ins;
uint32_t wc_ret_stack[WC_RET_STACK];
int wc_ret_depth;
uint32_t wc_image_lo, wc_image_hi;
uint64_t wc_video_writes;
uint8_t *wc_image_copy;

/* Generated by WcRecomp.java: sorted instruction addresses and the function containing each. */
extern const uint32_t wc_code_count;
extern const uint32_t wc_code_addr[];
extern void (*const wc_code_func[])(uint32_t);

static int find_code(uint32_t linear)
{
	uint32_t lo = 0, hi = wc_code_count;
	while (lo < hi) {
		uint32_t mid = (lo + hi) / 2;
		if (wc_code_addr[mid] < linear) {
			lo = mid + 1;
		}
		else {
			hi = mid;
		}
	}
	return lo < wc_code_count && wc_code_addr[lo] == linear ? (int)lo : -1;
}

int bios_entry(uint32_t linear);

/* Generated: overlay segments (relative to the load segment) and the size of the original image. */
extern const uint32_t wc_overlay_count;
extern const uint16_t wc_overlay_seg[];
extern const uint32_t wc_program_size;
/* Generated (wc_drivers.c): the recompiled drivers. */
extern const struct wc_driver *const wc_drivers[];
extern const uint32_t wc_driver_count;

uint8_t wc_codemap[MEM_SIZE / 8];

/* Whether a transfer to linear with the current CS reaches the program (recompiled) rather than
 * code it loaded at runtime. Heap memory can overlap the flattened overlays' addresses, but
 * overlay code always runs with CS exactly at its segment. */
static int is_program(uint32_t linear)
{
	if (linear >= wc_image_lo && linear < wc_image_lo + wc_program_size) {
		return 1;
	}
	uint16_t rel = (uint16_t)(rd(R_CS, 2) - wc_image_lo / 16);
	for (uint32_t i = 0; i < wc_overlay_count; i++) {
		if (wc_overlay_seg[i] == rel) {
			return 1;
		}
	}
	return 0;
}

/* ---- drivers loaded at runtime ---- */

static struct { uint16_t seg; const struct wc_driver *d; } loaded[32];
static int nloaded;

static const struct wc_driver *registered(uint16_t seg)
{
	for (int i = 0; i < nloaded; i++) {
		if (loaded[i].seg == seg) return loaded[i].d;
	}
	return NULL;
}

/* A recompiled driver whose instruction bytes are what is in memory at seg:0000. Registers it,
 * so that writes into those bytes (self-modifying code) are reported. */
static const struct wc_driver *driver_at(uint16_t seg)
{
	const struct wc_driver *d = registered(seg);
	if (d) return d;
	for (uint32_t i = 0; i < wc_driver_count; i++) {
		const struct wc_driver *c = wc_drivers[i];
		uint32_t r = 0;
		for (; r < c->nranges; r++) {
			if (memcmp(M + seg * 16 + c->ranges[r][0], c->image + c->ranges[r][0], c->ranges[r][1])) break;
		}
		if (r < c->nranges || nloaded == 32) continue;
		loaded[nloaded].seg = seg;
		loaded[nloaded++].d = c;
		for (r = 0; r < c->nranges; r++) {
			for (uint32_t k = 0; k < c->ranges[r][1]; k++) {
				uint32_t a = seg * 16 + c->ranges[r][0] + k;
				wc_codemap[a >> 3] |= (uint8_t)(1 << (a & 7));
			}
		}
		if (wc_trace) fprintf(stderr, "wc: driver %s loaded at %04x\n", c->name, seg);
		return c;
	}
	return NULL;
}

void code_write(uint32_t addr)
{
	static int reported;
	for (int i = 0; i < nloaded; i++) {
		uint32_t base = loaded[i].seg * 16u;
		if (addr - base < 0x10000 && reported < 20) {
			reported++;
			fprintf(stderr, "wc: self-modifying code: write to driver %s offset %04x by instruction %05x\n",
				loaded[i].d->name, addr - base, wc_last_ins);
			return;
		}
	}
}

uint32_t code_addr(uint64_t linear)
{
	uint16_t cs = (uint16_t)rd(R_CS, 2);
	const struct wc_driver *d = registered(cs);
	if (d && linear - cs * 16u < 0x10000) {
		return d->virt + (uint32_t)(linear - cs * 16u);
	}
	return linear >= wc_image_lo && linear < wc_image_hi ? (uint32_t)(linear - wc_reloc * 16) : (uint32_t)linear;
}

uint32_t runtime_addr(uint32_t code)
{
	if (code >= DRIVER_VIRT_SEG * 16u) {
		uint32_t base = code & ~0xffffu; /* drivers sit at 64 KB-aligned virtual segments */
		return (uint32_t)rd(R_CS, 2) * 16 + (code - base);
	}
	uint32_t lo = wc_image_lo - (uint32_t)(wc_reloc * 16), hi = wc_image_hi - (uint32_t)(wc_reloc * 16);
	return code >= lo && code < hi ? (uint32_t)(code + wc_reloc * 16) : code;
}

void pc_frame(uint32_t at);

/* The flight graphics driver's routine that copies the finished frame to the screen: entry 4 of
 * driver d7000 (drivers.txt fixes which driver gets which virtual segment). */
enum { FRAME_COPY = 0x77454 };

void run(uint32_t linear)
{
	if (bios_entry(linear)) {
		return;
	}
	if (!is_program(linear)) {
		uint32_t seg = (uint32_t)rd(R_CS, 2), off = (uint32_t)(linear - seg * 16);
		const struct wc_driver *d = driver_at((uint16_t)seg);
		if (d) {
			if (d->virt + off == FRAME_COPY) {
				pc_frame(FRAME_COPY);
			}
			run_code(d->virt + off);
			return;
		}
		fflush(stdout);
		fprintf(stderr, "wc: call into code loaded at runtime at %04x:%04x, which is not recompiled\n", seg, off);
		/* WC_LOADED_DIR: save the segment (64 KB from seg:0000) for recompilation ("npm run discover") */
		const char *dir = getenv("WC_LOADED_DIR");
		if (dir) {
			char path[1024];
			snprintf(path, sizeof path, "%s/%04x-%04x.bin", dir, seg, off);
			FILE *f = fopen(path, "wb");
			if (f) {
				fwrite(M + seg * 16, 1, 0x10000, f);
				fclose(f);
				fprintf(stderr, "wc: saved loaded code to %s\n", path);
			}
		}
		cpu_report(stderr);
		exit(5);
	}
	run_code(code_addr(linear));
}

static int find_in(const uint32_t *addr, uint32_t count, uint32_t code)
{
	uint32_t lo = 0, hi = count;
	while (lo < hi) {
		uint32_t mid = (lo + hi) / 2;
		if (addr[mid] < code) lo = mid + 1;
		else hi = mid;
	}
	return lo < count && addr[lo] == code ? (int)lo : -1;
}

void run_code(uint32_t code)
{
	if (code >= DRIVER_VIRT_SEG * 16u) {
		for (uint32_t i = 0; i < wc_driver_count; i++) {
			const struct wc_driver *d = wc_drivers[i];
			if (code - d->virt < 0x10000) {
				int k = find_in(d->addr, d->count, code);
				if (k >= 0) {
					d->func[k](code);
					return;
				}
			}
		}
	}
	else {
		int i = find_code(code);
		if (i >= 0) {
			wc_code_func[i](code);
			return;
		}
	}
	/* Exit code 4 + this line: "npm run discover" adds the address as an entry point. */
	fflush(stdout);
	fprintf(stderr, "wc: missing code at %05x\n", code);
	cpu_report(stderr);
	exit(4);
}

static void dump_regs(FILE *f)
{
	fprintf(f, "  AX=%04llx BX=%04llx CX=%04llx DX=%04llx SI=%04llx DI=%04llx BP=%04llx SP=%04llx\n",
		rd(R_AX, 2), rd(R_BX, 2), rd(R_CX, 2), rd(R_DX, 2), rd(R_SI, 2), rd(R_DI, 2), rd(R_BP, 2), rd(R_SP, 2));
	fprintf(f, "  CS=%04llx DS=%04llx ES=%04llx SS=%04llx  CF=%llu ZF=%llu SF=%llu OF=%llu\n",
		rd(R_CS, 2), rd(R_DS, 2), rd(R_ES, 2), rd(R_SS, 2), rd(R_CF, 1), rd(R_ZF, 1), rd(R_SF, 1), rd(R_OF, 1));
}

void pc_report(FILE *f);

extern uint8_t wc_palette[256][3];

/* WC_SCREENSHOT=file: the VGA palette (768 bytes, 6-bit) and the 320x200 frame buffer, raw. */
static void screenshot(void)
{
	const char *path = getenv("WC_SCREENSHOT");
	FILE *f = path ? fopen(path, "wb") : NULL;
	if (f) {
		fwrite(wc_palette, 1, sizeof wc_palette, f);
		fwrite(M + 0xa0000, 1, 320 * 200, f);
		fclose(f);
	}
}

void cpu_report(FILE *f)
{
	screenshot();
	pc_report(f);
	fprintf(f, "  %llu instructions executed, %llu writes to video memory\n", (unsigned long long)wc_icount,
		(unsigned long long)wc_video_writes);
	dump_regs(f);
	fprintf(f, "  called from (innermost first, code addresses after each call):");
	for (int i = wc_ret_depth - 1; i >= 0 && i >= wc_ret_depth - 8; i--) {
		fprintf(f, " %05x", wc_ret_stack[i]);
	}
	fprintf(f, "\n");
}

_Noreturn void cpu_fail(const char *what, uint32_t at)
{
	fflush(stdout);
	fprintf(stderr, "wc: %s %05x (CS=%04llx)\n", what, at, rd(R_CS, 2));
	cpu_report(stderr);
	exit(3);
}

_Noreturn void cpu_div0(uint32_t at)
{
	cpu_fail("divide error at", at);
}

void trace_ins(uint32_t at)
{
	fprintf(stderr, "  %05x  AX=%04llx BX=%04llx CX=%04llx DX=%04llx SP=%04llx DS=%04llx ES=%04llx IF=%llu\n", at,
		rd(R_AX, 2), rd(R_BX, 2), rd(R_CX, 2), rd(R_DX, 2), rd(R_SP, 2), rd(R_DS, 2), rd(R_ES, 2), rd(R_IF, 1));
}

void watch_hit(uint32_t addr, int size, uint64_t value)
{
	fprintf(stderr, "wc: write %0*llx to %05x (watch %05x) by instruction %05x, CS=%04llx\n", size * 2,
		(unsigned long long)value, addr, wc_watch, wc_last_ins, rd(R_CS, 2));
}

/* Writes at A000:0000 and above (video memory, BIOS); VGA output will hook in here. */
void mem_write_hook(uint32_t addr, int size)
{
	if (addr < 0xb0000) {
		wc_video_writes++;
	}
	(void)size;
}
